// Package legal embeds the licence information shown in the panel
// (Einstellungen › Über & Lizenzen). THIRD_PARTY_LICENSES.txt is generated by
// scripts/build-release.sh before the panel is compiled.
package legal

import (
	"embed"
	"io/fs"
)

//go:embed all:data
var data embed.FS

const License = "Apache-2.0"

// Notice returns the project's NOTICE file.
func Notice() string { return read("data/NOTICE") }

// ThirdParty returns THIRD_PARTY_LICENSES.txt, or "" in development builds.
func ThirdParty() string { return read("data/THIRD_PARTY_LICENSES.txt") }

func read(name string) string {
	b, err := fs.ReadFile(data, name)
	if err != nil {
		return ""
	}
	return string(b)
}
